macro.command:
// Reverse Gravity — targets that fail DEX save fall upward 100 feet
// If they hit a ceiling, they take fall damage (1d6 per 10 feet)
// If no ceiling, they hover at the top of the cylinder
const failedTargets = Array.from(workflow.failedSaves);
if (!failedTargets.length) return;

const { DialogV2 } = foundry.applications.api;
const result = await DialogV2.wait({
  window: { title: "Reverse Gravity — Ceiling Height" },
  content: `<p>How high is the ceiling above the affected area? (Targets fall upward up to 100 feet.)</p>
<p>Enter the ceiling height in feet, or 0 if there is no ceiling (targets hover at top).</p>
<div class="form-group"><label>Ceiling Height (ft)</label><input type="number" name="height" value="0" min="0" max="100" style="width:80px"></div>`,
  rejectClose: false,
  buttons: [
    { action: "confirm", label: "Apply", default: true, callback: (event, button) => {
      return parseInt(button.form.elements.height?.value) || 0;
    }},
    { action: "cancel", label: "Cancel" }
  ]
});

if (result === undefined || result === null || result === "cancel") return;
const ceilingHeight = Math.min(Math.max(result, 0), 100);

if (ceilingHeight <= 0) {
  ChatMessage.create({content: `<strong>Reverse Gravity</strong>: ${failedTargets.map(t => t.name).join(", ")} fall upward and hover at the top of the cylinder (100 ft). No fall damage — they will fall when the spell ends.`, speaker: ChatMessage.getSpeaker({token: workflow.token})});
  return;
}

// Calculate fall damage: 1d6 per 10 feet
const d6Count = Math.floor(ceilingHeight / 10);
if (d6Count <= 0) return;

const targetDamages = [];
for (const token of failedTargets) {
  const dmgRoll = await new Roll(`${d6Count}d6`).evaluate();
  targetDamages.push({
    token,
    damageDetail: [{value: dmgRoll.total, type: "bludgeoning", properties: new Set(["mgc"])}],
    totalDamage: dmgRoll.total
  });
}

ChatMessage.create({content: `<strong>Reverse Gravity</strong>: ${failedTargets.map(t => t.name).join(", ")} fall upward ${ceilingHeight} ft and strike the ceiling, taking ${d6Count}d6 bludgeoning damage.`, speaker: ChatMessage.getSpeaker({token: workflow.token})});

if (targetDamages.length) {
  await MidiQOL.applyTokenDamageMany(targetDamages, workflow.item, {workflow, forceApply: false});
}
